def transform(g):
    h,w=len(g),len(g[0]); n=(w+2)//3
    blocks=[[r[3*k:min(3*k+3,w)] for r in g] for k in range(n)]
    def bit(i,k):
        if k<n-1: return int(g[i][3*k+1]==0 and g[i][3*k+2]==0)
        return int(g[i][w-1]==0)
    keys=[sum(bit(i,k) for i in range(1,h,2)) for k in range(n)]
    order=sorted(range(n),key=lambda k:-keys[k])
    print('keys',keys,'order',order)
    return [[cell for k in order for cell in blocks[k][i]] for i in range(h)]
